/// <summary>
/// AVA/WEN/2024/10/30      AVA_012673_ItemDescription
/// </summary>
/// <param name = "_inventTable">InventTable</param>
/// <param name = "_languageId">LanguageId</param>
/// <param name = "_inventDimId">InventDimId</param>
/// <param name = "_ecoResCategory">EcoResCategory</param>
/// <returns>ItemFreeTxt</returns>
public static ItemFreeTxt nameAndOrDescription(InventTable _inventTable, LanguageId _languageId, InventDimId _inventDimId, EcoResCategory _ecoResCategory)
{
    ItemFreeTxt description, ret;

    ret = next nameAndOrDescription(_inventTable, _languageId, _inventDimId, _ecoResCategory);

    if (!VendFormletterParameters::find().ItemNameAndTxt2Description)
    {
        if (_inventTable)
        {
            description  = _inventTable.productDescription(_languageId, _inventDimId);
        }
        else if (_ecoResCategory && _languageId)
        {
            EcoResCategoryTranslation categoryTranslation = EcoResCategoryTranslation::find(_ecoResCategory.RecId, _languageId);
            description = categoryTranslation ? categoryTranslation.Description : EcoResCategoryTranslation::find(_ecoResCategory.RecId, LanguageTable::defaultLanguage()).Description;
        }

        ret = description;
    }


    return ret;
}
